	check, result := e.check, &e.result
	timeout := check.TimeoutSeconds
	if timeout <= 0 {
		timeout = matrix.Defaults.TimeoutSeconds
	}
	if timeout <= 0 {
		timeout = 600 // documented safe default
	}
