	capture := &tailBuffer{capacity: 4096}
	limiter := &outputLimiter{limit: maxOutput, cancel: cancel}
	packages := &goTestPackages{}
	execArgs := sanitizeGoCheckArgs(ctx, e.moduleDir, check.Program, check.Args)
	if parent.Err() != nil {
		cancel()
		e.markCancelled()
		return
